/**
 * tests/adversarial-prod2-config-cascade.js
 * 
 * Empirical Adversarial Challenger Test Suite:
 * Configuration Resolution Cascade & Dynamic Rollback Keepalive Immunity
 * 
 * Target Device: LG 32LR686BPSA (webOS 8.5.0, Chromium ~108 WAM)
 * Author: challenger_prod_2_1 (Empirical Challenger)
 * 
 * Mission Focus:
 * 1. Malformed JSON & pathological types in PalmSystem.launchParams
 * 2. Conflicting combinations: launchParams vs URL query vs localStorage vs defaults
 * 3. Edge-case URLs: trailing slashes, spaces, invalid port numbers, non-HTTP schemes
 * 4. Verification that dynamic rollback overrides are immune to keepalive port updates
 */

'use strict';

const fs = require('fs');
const path = require('path');
const http = require('http');
const assert = require('assert');

// Resolve JSDOM
let JSDOM;
try {
  JSDOM = require('jsdom').JSDOM;
} catch (e1) {
  try {
    JSDOM = require('/home/prem/monkeytype/monkeytype/node_modules/.pnpm/jsdom@27.4.0_supports-color@10.2.2/node_modules/jsdom').JSDOM;
  } catch (e2) {
    try {
      JSDOM = require('/home/prem/Documents/movies/netflix/node_modules/jsdom').JSDOM;
    } catch (e3) {
      throw new Error('JSDOM module could not be resolved: ' + e1.message);
    }
  }
}

const ROOT_DIR = path.resolve(__dirname, '..');
const htmlPath = path.resolve(ROOT_DIR, 'app/index.html');
const configPath = path.resolve(ROOT_DIR, 'app/js/config.js');
const navPath = path.resolve(ROOT_DIR, 'app/js/navigation.js');
const tmdbPath = path.resolve(ROOT_DIR, 'app/js/tmdb.js');
const homePath = path.resolve(ROOT_DIR, 'app/js/views/home.js');
const catalogPath = path.resolve(ROOT_DIR, 'app/js/views/catalog.js');
const searchPath = path.resolve(ROOT_DIR, 'app/js/views/search.js');
const detailsPath = path.resolve(ROOT_DIR, 'app/js/views/details.js');
const playerPath = path.resolve(ROOT_DIR, 'app/js/player.js');
const appPath = path.resolve(ROOT_DIR, 'app/js/app.js');

// ANSI Terminal Colors
const C = {
  reset: '\x1b[0m',
  bold: '\x1b[1m',
  green: '\x1b[32m',
  red: '\x1b[31m',
  yellow: '\x1b[33m',
  cyan: '\x1b[36m',
  gray: '\x1b[90m',
  magenta: '\x1b[35m'
};

let totalChecks = 0;
let passedChecks = 0;
let failedChecks = 0;
const findings = [];

async function check(id, title, fn) {
  totalChecks++;
  const label = `[ADV-P2] [${id}] ${title}`;
  try {
    await fn();
    passedChecks++;
    console.log(`  ${C.green}✔ PASS${C.reset} ${label}`);
  } catch (err) {
    failedChecks++;
    console.error(`  ${C.red}✖ FAIL${C.reset} ${label}`);
    console.error(`      ${C.red}${err.stack || err.message}${C.reset}`);
    findings.push({ id, title, error: err.message, stack: err.stack });
  }
}

/**
 * Creates an isolated DOM environment with full script stack
 */
function createHarness(options = {}) {
  const html = fs.readFileSync(htmlPath, 'utf8');
  const url = options.url || 'http://127.0.0.1:8088/#home';

  const dom = new JSDOM(html, {
    url: url,
    runScripts: 'outside-only'
  });
  const { window } = dom;

  // Initialize localStorage
  window.localStorage.clear();
  if (options.localStorage) {
    for (const k in options.localStorage) {
      if (Object.prototype.hasOwnProperty.call(options.localStorage, k)) {
        window.localStorage.setItem(k, options.localStorage[k]);
      }
    }
  }

  // Mock PalmSystem
  if (options.palmSystem !== undefined) {
    window.PalmSystem = options.palmSystem;
  }

  // Mock Bridges
  if (options.mockPalmBridge) {
    window.PalmServiceBridge = options.mockPalmBridge;
  }
  if (options.mockWebOSBridge) {
    window.WebOSServiceBridge = options.mockWebOSBridge;
  }
  if (options.mockWebOSTV) {
    window.webOSTV = options.mockWebOSTV;
  }

  // Fetch interceptor
  let lastFetchedUrl = null;
  let lastFetchOpts = null;
  window.fetch = function (reqUrl, opts) {
    lastFetchedUrl = reqUrl;
    lastFetchOpts = opts;
    if (typeof options.onFetch === 'function') {
      try { options.onFetch(reqUrl, opts); } catch (_) {}
    }
    return Promise.resolve({
      ok: true,
      status: 200,
      json: () => Promise.resolve({ success: true, results: [], streamUrl: 'http://127.0.0.1:8089/hls/proxy?url=test' }),
      text: () => Promise.resolve('ok')
    });
  };

  // Evaluate scripts in order
  window.eval(fs.readFileSync(configPath, 'utf8'));
  window.eval(fs.readFileSync(navPath, 'utf8'));
  window.eval(fs.readFileSync(tmdbPath, 'utf8'));
  window.eval(fs.readFileSync(homePath, 'utf8'));
  window.eval(fs.readFileSync(catalogPath, 'utf8'));
  window.eval(fs.readFileSync(searchPath, 'utf8'));
  window.eval(fs.readFileSync(detailsPath, 'utf8'));
  window.eval(fs.readFileSync(playerPath, 'utf8'));
  window.eval(fs.readFileSync(appPath, 'utf8'));

  if (!options.skipAppInit) {
    window.CinejoyApp.init();
  }

  return {
    dom,
    window,
    document: window.document,
    config: window.CINEJOY_CONFIG,
    app: window.CinejoyApp,
    player: window.PlayerController,
    nav: window.SpatialNav,
    getLastFetchedUrl: () => lastFetchedUrl,
    getLastFetchOpts: () => lastFetchOpts
  };
}

async function runAdversarialSuite() {
  console.log(`\n${C.bold}${C.magenta}================================================================================${C.reset}`);
  console.log(`${C.bold}► ADVERSARIAL CHALLENGER SUITE: CONFIG RESOLUTION CASCADE & ROLLBACK IMMUNITY${C.reset}`);
  console.log(`${C.magenta}================================================================================${C.reset}\n`);

  // ===========================================================================
  // SECTION 1: Malformed & Pathological launchParams Stress Tests
  // ===========================================================================
  console.log(`${C.bold}${C.cyan}► Section 1: Malformed JSON & Pathological PalmSystem.launchParams${C.reset}`);

  await check('T1.1', 'Unclosed JSON string in launchParams falls back safely to default', () => {
    const { config } = createHarness({
      palmSystem: { launchParams: '{"proxyUrl": "http://192.168.1.6:8088"' } // missing }
    });
    assert.strictEqual(config.proxyBaseUrl, 'http://127.0.0.1:8088', 'Must fall back to default');
    assert.strictEqual(config.hasExplicitProxyOverride, false, 'hasExplicitProxyOverride must be false');
    assert.strictEqual(config.proxySource, 'default', 'proxySource must be default');
  });

  await check('T1.2', 'Unquoted keys in launchParams falls back safely to default', () => {
    const { config } = createHarness({
      palmSystem: { launchParams: '{proxyUrl: "http://192.168.1.6:8088"}' }
    });
    assert.strictEqual(config.proxyBaseUrl, 'http://127.0.0.1:8088');
    assert.strictEqual(config.hasExplicitProxyOverride, false);
    assert.strictEqual(config.proxySource, 'default');
  });

  await check('T1.3', 'Single-quoted JSON in launchParams falls back safely to default', () => {
    const { config } = createHarness({
      palmSystem: { launchParams: "{'proxyUrl': 'http://192.168.1.6:8088'}" }
    });
    assert.strictEqual(config.proxyBaseUrl, 'http://127.0.0.1:8088');
    assert.strictEqual(config.hasExplicitProxyOverride, false);
    assert.strictEqual(config.proxySource, 'default');
  });

  await check('T1.4', 'Trailing comma syntax error in launchParams falls back safely to default', () => {
    const { config } = createHarness({
      palmSystem: { launchParams: '{"proxyUrl": "http://192.168.1.6:8088",}' }
    });
    assert.strictEqual(config.proxyBaseUrl, 'http://127.0.0.1:8088');
    assert.strictEqual(config.hasExplicitProxyOverride, false);
    assert.strictEqual(config.proxySource, 'default');
  });

  await check('T1.5', 'JSON string "null" in launchParams falls back safely to default', () => {
    const { config } = createHarness({
      palmSystem: { launchParams: 'null' }
    });
    assert.strictEqual(config.proxyBaseUrl, 'http://127.0.0.1:8088');
    assert.strictEqual(config.hasExplicitProxyOverride, false);
    assert.strictEqual(config.proxySource, 'default');
  });

  await check('T1.6', 'Primitive literals ("true", "false", "12345", "") in launchParams fall back safely', () => {
    const primitives = ['true', 'false', '12345', '', '   ', '\t\n\r'];
    for (const prim of primitives) {
      const { config } = createHarness({ palmSystem: { launchParams: prim } });
      assert.strictEqual(config.proxyBaseUrl, 'http://127.0.0.1:8088', `Primitive "${prim}" must fall back to default`);
      assert.strictEqual(config.hasExplicitProxyOverride, false);
    }
  });

  await check('T1.7', 'JSON Array in launchParams ([1,2,3] or [{"proxyUrl":...}]) falls back safely', () => {
    const { config: c1 } = createHarness({ palmSystem: { launchParams: '[1, 2, 3]' } });
    assert.strictEqual(c1.proxyBaseUrl, 'http://127.0.0.1:8088');
    assert.strictEqual(c1.hasExplicitProxyOverride, false);

    const { config: c2 } = createHarness({ palmSystem: { launchParams: '[{"proxyUrl":"http://192.168.1.6:8088"}]' } });
    assert.strictEqual(c2.proxyBaseUrl, 'http://127.0.0.1:8088');
    assert.strictEqual(c2.hasExplicitProxyOverride, false);
  });

  await check('T1.8', 'Non-string launchParams (number, boolean, null, undefined, function, Symbol) survive', () => {
    const types = [42, true, false, null, undefined, function () {}, Symbol('stress')];
    for (const t of types) {
      const { config } = createHarness({ palmSystem: { launchParams: t } });
      assert.strictEqual(config.proxyBaseUrl, 'http://127.0.0.1:8088', `Type ${typeof t} must survive and fall back`);
      assert.strictEqual(config.hasExplicitProxyOverride, false);
    }
  });

  await check('T1.9', 'Query-string fallback in launchParams successfully extracts proxyUrl', () => {
    const { config } = createHarness({
      palmSystem: { launchParams: 'proxyUrl=http%3A%2F%2F192.168.1.6%3A8088&logLevel=debug' }
    });
    assert.strictEqual(config.proxyBaseUrl, 'http://192.168.1.6:8088');
    assert.strictEqual(config.hasExplicitProxyOverride, true);
    assert.strictEqual(config.proxySource, 'launchParams');
  });

  await check('T1.10', 'Malformed URI percent encoding (%ZZ, %E0%A4, %) in fallback catches URIError safely', () => {
    const malformed = [
      'proxyUrl=http://192.168.1.6:8088%ZZ',
      'bad=%E0%A4',
      'trailing=%',
      '%%%',
      'key%ZZ=val'
    ];
    for (const str of malformed) {
      const { config } = createHarness({ palmSystem: { launchParams: str } });
      assert.strictEqual(config.proxyBaseUrl, 'http://127.0.0.1:8088', `Malformed encoding "${str}" must not throw and must fall back`);
      assert.strictEqual(config.hasExplicitProxyOverride, false);
    }
  });

  await check('T1.11', 'Prototype pollution attack in launchParams does not pollute Object.prototype', () => {
    const payload = JSON.stringify({
      '__proto__': { 'pollutedKey': 'attack_successful' },
      'constructor': { 'prototype': { 'pollutedProto': 'attack_successful' } },
      'proxyUrl': 'http://192.168.1.6:8088'
    });
    const { config } = createHarness({ palmSystem: { launchParams: payload } });
    assert.strictEqual(config.proxyBaseUrl, 'http://192.168.1.6:8088');
    assert.strictEqual(Object.prototype.pollutedKey, undefined, 'Object.prototype must not be polluted');
    assert.strictEqual(Object.prototype.pollutedProto, undefined, 'Object.prototype must not be polluted');
    delete Object.prototype.pollutedKey;
    delete Object.prototype.pollutedProto;
  });

  await check('T1.12', 'Oversized launchParams payload (250KB) parses without catastrophic lag', () => {
    const largeObj = { proxyUrl: 'http://192.168.1.6:8088' };
    for (let i = 0; i < 2000; i++) {
      largeObj['key_' + i] = 'val_' + 'x'.repeat(100);
    }
    const t0 = Date.now();
    const { config } = createHarness({ palmSystem: { launchParams: JSON.stringify(largeObj) } });
    const duration = Date.now() - t0;
    assert.strictEqual(config.proxyBaseUrl, 'http://192.168.1.6:8088');
    assert.ok(duration < 500, `Parsing 250KB took ${duration}ms (target < 500ms)`);
  });

  // ===========================================================================
  // SECTION 2: Conflicting Combinations Matrix
  // ===========================================================================
  console.log(`\n${C.bold}${C.cyan}► Section 2: Conflicting Combinations Precedence Matrix${C.reset}`);

  await check('T2.1', 'Full Conflict: launchParams vs URL query vs localStorage vs default -> launchParams strictly wins', () => {
    const { config, player } = createHarness({
      palmSystem: { launchParams: JSON.stringify({ proxyUrl: 'http://10.0.0.1:8088' }) },
      url: 'http://127.0.0.1:8088/?proxyUrl=http://10.0.0.2:8088#home',
      localStorage: { cinejoy_proxy_url: 'http://10.0.0.3:8088' }
    });
