    assert.ok(typeof bridgeCallback === 'function', 'Bridge callback must be registered');
    bridgeCallback(JSON.stringify({ returnValue: true, port: 8089, uptime: 10 }));

    assert.strictEqual(harness.config.proxyBaseUrl, 'http://192.168.1.6:8088', 'Must NOT be overwritten by port 8089');
