    assert.strictEqual(h2.config.proxyBaseUrl, 'http://192.168.1.6:8088', 'webOSTV.service respects override immunity');
  });

  // ===========================================================================
  // Summary & Scorecard
  // ===========================================================================
  console.log(`\n${C.bold}--------------------------------------------------------------------------------${C.reset}`);
  console.log(`${C.bold}ADVERSARIAL CHALLENGER SUITE EXECUTION SUMMARY${C.reset}`);
  console.log(`  Total Discrete Checks Executed:  ${C.bold}${totalChecks}${C.reset}`);
