  if (findings.length > 0) {
    console.log(`${C.yellow}${C.bold}DISCOVERED FINDINGS / VULNERABILITIES:${C.reset}`);
    findings.forEach(f => {
      console.log(`- [${f.id}] ${f.title}: ${f.error}`);
    });
  }

  return { totalChecks, passedChecks, failedChecks, findings };
}

